1	/**
2	 * Wave 2 games — make Factorio, Garry's Mod, Conan Exiles, Unturned, The Forest,
3	 * Sons of the Forest and Minecraft Bedrock orderable. Same Docker/OsTemplate pattern
4	 * as Wave 1. (DayZ is deferred — its server needs a licensed Steam account.)
5	 *
6	 * Run: cd /opt/nxeon && npx tsx prisma/seed-wave2-games.ts   (idempotent)
7	 *
8	 * NOTE: static in-container placeholder passwords ("changeme12"/blank) — customers
9	 * change them post-deploy. The Forest/SotF crash-loop on a DEFAULT password by design,
10	 * so their recipes must seed a non-default one (validate before promoting those two).
11	 */
12	import { PrismaClient } from "@prisma/client";
13	
14	const db = new PrismaClient();
15	
16	type Template = { family: string; name: string; setupScript: string; minRamMB: number; minDiskGB: number };
17	
18	const TEMPLATES: Template[] = [
19	  {
20	    family: "factorio", name: "Factorio Server", minRamMB: 2048, minDiskGB: 10,
21	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/factorio && chown 845:845 /opt/factorio && docker run -d --name factorio -e GENERATE_NEW_SAVE=true -e LOAD_LATEST_SAVE=true -e SAVE_NAME=nxeon -p 34197:34197/udp -p 27015:27015/tcp -v /opt/factorio:/factorio --restart unless-stopped factoriotools/factorio:stable`,
22	  },
23	  {
24	    family: "gmod", name: "Garry's Mod Server", minRamMB: 2048, minDiskGB: 15,
25	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/gmod && docker run -d --name gmod -e GAME_PARAMS="-secure +gamemode sandbox +map gm_construct +maxplayers 16" -e VALIDATE=true -p 27015:27015/tcp -p 27015:27015/udp -p 27005:27005/udp -v /opt/gmod:/serverdata/serverfiles --restart unless-stopped ghcr.io/ich777/steamcmd:garrysmod`,
26	  },
27	  {
28	    family: "conan", name: "Conan Exiles Server", minRamMB: 6144, minDiskGB: 30,
29	    setupScript: `curl -fsSL https://get.docker.com | sh && docker run -d --name conan -p 7777:7777/udp -p 7777:7777/tcp -p 7778:7778/udp -p 27015:27015/udp -e GAME_INSTANCE_NAME=nxeon -e GAME_SERVER_NAME="Nxeon Conan Server" -e GAME_SERVER_PASSWORD="" -v /opt/conan/game:/conanexiles -v /opt/conan/config:/conanexiles_config --restart unless-stopped melle2/conanexiles-ds:latest`,
30	  },
31	  {
32	    family: "unturned", name: "Unturned Server", minRamMB: 2048, minDiskGB: 10,
33	    setupScript: `curl -fsSL https://get.docker.com | sh && docker run -d --name unturned -p 27015-27017:27015-27017/udp -p 27015-27017:27015-27017/tcp -v /opt/unturned:/config -e SERVER_ID=nxeon -e INTERNET_SERVER=true --restart unless-stopped fragsoc/unturned`,
34	  },
35	  {
36	    family: "theforest", name: "The Forest Server", minRamMB: 4096, minDiskGB: 20,
37	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/theforest && docker run -d --name theforest -p 27015-27016:27015-27016/udp -p 8766:8766/udp -v /opt/theforest:/theforest -e PUID=1000 -e PGID=1000 -e ALWAYS_UPDATE_ON_START=true -e FILTER_SHADER_AND_MESH_AND_WINE_DEBUG=true --restart unless-stopped jammsen/the-forest-dedicated-server:latest`,
38	  },
39	  {
40	    family: "sonsoftheforest", name: "Sons of the Forest Server", minRamMB: 4096, minDiskGB: 25,
41	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/sonsoftheforest && docker run -d --name sonsoftheforest -p 8766:8766/udp -p 27016:27016/udp -p 9700:9700/udp -v /opt/sonsoftheforest:/sonsoftheforest -e PUID=1000 -e PGID=1000 -e ALWAYS_UPDATE_ON_START=true -e SKIP_NETWORK_ACCESSIBILITY_TEST=true -e FILTER_SHADER_AND_MESH_AND_WINE_DEBUG=true --restart unless-stopped jammsen/sons-of-the-forest-dedicated-server:latest`,
42	  },
43	  {
44	    family: "bedrock", name: "Minecraft Bedrock Server", minRamMB: 1024, minDiskGB: 5,
45	    setupScript: `curl -fsSL https://get.docker.com | sh && docker run -d --name bedrock -e EULA=TRUE -e SERVER_NAME="Nxeon Bedrock Server" -e GAMEMODE=survival -e DIFFICULTY=normal -e LEVEL_NAME=Bedrock -e MAX_PLAYERS=10 -e ALLOW_CHEATS=false -e VERSION=LATEST -p 19132:19132/udp -v /opt/bedrock:/data --restart unless-stopped itzg/minecraft-bedrock-server`,
46	  },
47	];
48	
49	type TierSpec = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };
50	
51	const TIERS: TierSpec[] = [
52	  { gameFamily: "factorio", name: "Factorio — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 10, slots: 8, priceCents: 299 },
53	  { gameFamily: "factorio", name: "Factorio — 3 GB / 32 players", ramMB: 3072, cpuCores: 2, diskGB: 20, slots: 32, priceCents: 599, featured: true },
54	  { gameFamily: "factorio", name: "Factorio — 4 GB / 100 players", ramMB: 4096, cpuCores: 3, diskGB: 40, slots: 100, priceCents: 999 },
55	
56	  { gameFamily: "gmod", name: "Garry's Mod — 2 GB / 12 slots", ramMB: 2048, cpuCores: 1, diskGB: 15, slots: 12, priceCents: 399 },
57	  { gameFamily: "gmod", name: "Garry's Mod — 4 GB / 24 slots", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 24, priceCents: 799, featured: true },
58	  { gameFamily: "gmod", name: "Garry's Mod — 6 GB / 64 slots", ramMB: 6144, cpuCores: 3, diskGB: 50, slots: 64, priceCents: 1399 },
59	
60	  { gameFamily: "conan", name: "Conan Exiles — 6 GB / 20 slots", ramMB: 6144, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 1499 },
61	  { gameFamily: "conan", name: "Conan Exiles — 8 GB / 40 slots", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 40, priceCents: 2499, featured: true },
62	  { gameFamily: "conan", name: "Conan Exiles — 12 GB / 70 slots", ramMB: 12288, cpuCores: 4, diskGB: 80, slots: 70, priceCents: 3999 },
63	
64	  { gameFamily: "unturned", name: "Unturned — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 10, slots: 8, priceCents: 399 },
65	  { gameFamily: "unturned", name: "Unturned — 3 GB / 16 players", ramMB: 3072, cpuCores: 2, diskGB: 15, slots: 16, priceCents: 699, featured: true },
66	  { gameFamily: "unturned", name: "Unturned — 4 GB / 24 players", ramMB: 4096, cpuCores: 2, diskGB: 25, slots: 24, priceCents: 999 },
67	
68	  { gameFamily: "theforest", name: "The Forest — 4 GB / 4 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 4, priceCents: 899 },
69	  { gameFamily: "theforest", name: "The Forest — 6 GB / 8 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 8, priceCents: 1299, featured: true },
70	
71	  { gameFamily: "sonsoftheforest", name: "Sons of the Forest — 4 GB / 4 players", ramMB: 4096, cpuCores: 2, diskGB: 25, slots: 4, priceCents: 999 },
72	  { gameFamily: "sonsoftheforest", name: "Sons of the Forest — 6 GB / 8 players", ramMB: 6144, cpuCores: 3, diskGB: 30, slots: 8, priceCents: 1499, featured: true },
73	
74	  { gameFamily: "bedrock", name: "Bedrock — 1 GB / 5 players", ramMB: 1024, cpuCores: 1, diskGB: 5, slots: 5, priceCents: 299 },
75	  { gameFamily: "bedrock", name: "Bedrock — 2 GB / 10 players", ramMB: 2048, cpuCores: 1, diskGB: 10, slots: 10, priceCents: 499, featured: true },
76	  { gameFamily: "bedrock", name: "Bedrock — 4 GB / 40 players", ramMB: 4096, cpuCores: 2, diskGB: 40, slots: 40, priceCents: 1199 },
77	];
78	
79	async function main() {
80	  const templateIdByFamily = new Map<string, string>();
81	  let sort = 40;
82	  for (const t of TEMPLATES) {
83	    const os = await db.osTemplate.upsert({
84	      where: { slug: t.family },
85	      create: {
86	        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
87	        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
88	        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
89	      },
90	      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
91	    });
92	    templateIdByFamily.set(t.family, os.id);
93	    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
94	  }
95	
96	  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
97	  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
98	  const largest = plans[plans.length - 1];
99	
100	  let created = 0, updated = 0;
101	  const sortByGame = new Map<string, number>();
102	  for (const spec of TIERS) {
103	    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
104	    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
105	    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
106	    sortByGame.set(spec.gameFamily, sortOrder + 1);
107	    const data = {
108	      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
109	      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
110	      featured: spec.featured ?? false, active: true, sortOrder,
111	    };
112	    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
113	    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
114	    else { await db.gamePlan.create({ data }); created++; }
115	    console.log(`  plan ${spec.name.padEnd(38)} base=${basePlan.name}`);
116	  }
117	  console.log(`\nWave 2: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
118	}
119	
120	main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());
121

1	/**
2	 * Wave 1 games — make ARK, Satisfactory, Project Zomboid, 7 Days to Die, V Rising
3	 * and Enshrouded orderable. Each is a Docker container (community image) installed
4	 * by the OsTemplate.setupScript in cloud-init — same pattern as Minecraft/Rust/Valheim.
5	 *
6	 * Creates:
7	 *   1. An OsTemplate per game (family=<game>, category=APPLICATION, setupScript = the
8	 *      one-line docker run). Clones the golden Ubuntu template (baseVmid 9000).
9	 *   2. GamePlan tiers, each wired to the smallest active VPS Plan whose ramMB >= the
10	 *      tier's ramMB + this game's OsTemplate.
11	 *
12	 * Idempotent: OsTemplates upsert by slug; GamePlans dedupe by (gameFamily, name).
13	 * Run: cd /opt/nxeon && npx tsx prisma/seed-wave1-games.ts
14	 *
15	 * NOTE: default in-container passwords are the static placeholder "changeme12"
16	 * (matching the existing Valheim template) — customers change them post-deploy.
17	 * A per-order random-secret injection is a follow-up security refinement.
18	 */
19	import { PrismaClient } from "@prisma/client";
20	
21	const db = new PrismaClient();
22	
23	type Template = {
24	  family: string;
25	  name: string;
26	  setupScript: string;
27	  minRamMB: number;
28	  minDiskGB: number;
29	};
30	
