92	
93	const TIERS: TierSpec[] = [
94	  // ARK — very RAM-heavy.
95	  { gameFamily: "ark", name: "ARK — 8 GB / 20 slots", ramMB: 8192, cpuCores: 2, diskGB: 40, slots: 20, priceCents: 1499 },
96	  { gameFamily: "ark", name: "ARK — 16 GB / 50 slots", ramMB: 16384, cpuCores: 4, diskGB: 80, slots: 50, priceCents: 2799, featured: true },
97	  { gameFamily: "ark", name: "ARK — 32 GB / 100 slots", ramMB: 32768, cpuCores: 6, diskGB: 160, slots: 100, priceCents: 4999 },
98	
99	  // Satisfactory — scales with factory size.
100	  { gameFamily: "satisfactory", name: "Satisfactory — 8 GB / 4 players", ramMB: 8192, cpuCores: 2, diskGB: 20, slots: 4, priceCents: 1200 },
101	  { gameFamily: "satisfactory", name: "Satisfactory — 12 GB / 8 players", ramMB: 12288, cpuCores: 4, diskGB: 40, slots: 8, priceCents: 2000, featured: true },
102	  { gameFamily: "satisfactory", name: "Satisfactory — 16 GB / 16 players", ramMB: 16384, cpuCores: 6, diskGB: 60, slots: 16, priceCents: 3200 },
103	
104	  // Project Zomboid — B42 is heavy.
105	  { gameFamily: "projectzomboid", name: "Project Zomboid — 6 GB / 8 players", ramMB: 6144, cpuCores: 2, diskGB: 15, slots: 8, priceCents: 900 },
106	  { gameFamily: "projectzomboid", name: "Project Zomboid — 8 GB / 16 players", ramMB: 8192, cpuCores: 3, diskGB: 25, slots: 16, priceCents: 1500, featured: true },
107	  { gameFamily: "projectzomboid", name: "Project Zomboid — 12 GB / 32 players", ramMB: 12288, cpuCores: 4, diskGB: 40, slots: 32, priceCents: 2400 },
108	
109	  // 7 Days to Die — CPU + RAM hungry.
110	  { gameFamily: "sdtd", name: "7 Days to Die — 8 GB / 4 players", ramMB: 8192, cpuCores: 3, diskGB: 25, slots: 4, priceCents: 1400 },
111	  { gameFamily: "sdtd", name: "7 Days to Die — 10 GB / 8 players", ramMB: 10240, cpuCores: 4, diskGB: 40, slots: 8, priceCents: 2000, featured: true },
112	  { gameFamily: "sdtd", name: "7 Days to Die — 16 GB / 16 players", ramMB: 16384, cpuCores: 6, diskGB: 70, slots: 16, priceCents: 2800 },
113	
114	  // V Rising — Wine + heavy sim.
115	  { gameFamily: "vrising", name: "V Rising — 6 GB / 20 players", ramMB: 6144, cpuCores: 2, diskGB: 20, slots: 20, priceCents: 1200 },
116	  { gameFamily: "vrising", name: "V Rising — 8 GB / 40 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 40, priceCents: 1800, featured: true },
117	  { gameFamily: "vrising", name: "V Rising — 12 GB / 80 players", ramMB: 12288, cpuCores: 4, diskGB: 40, slots: 80, priceCents: 2600 },
118	
119	  // Enshrouded — Proton + large voxel world.
120	  { gameFamily: "enshrouded", name: "Enshrouded — 6 GB / 8 players", ramMB: 6144, cpuCores: 2, diskGB: 30, slots: 8, priceCents: 1400 },
121	  { gameFamily: "enshrouded", name: "Enshrouded — 10 GB / 12 players", ramMB: 10240, cpuCores: 4, diskGB: 40, slots: 12, priceCents: 2200, featured: true },
122	  { gameFamily: "enshrouded", name: "Enshrouded — 16 GB / 16 players", ramMB: 16384, cpuCores: 6, diskGB: 60, slots: 16, priceCents: 3400 },
