125	async function main() {
126	  // 1. OsTemplates (clone the golden Ubuntu template, vmid 9000, like the others).
127	  const templateIdByFamily = new Map<string, string>();
128	  let sort = 30;
129	  for (const t of TEMPLATES) {
130	    const os = await db.osTemplate.upsert({
131	      where: { slug: t.family },
132	      create: {
133	        slug: t.family,
134	        name: t.name,
135	        category: "APPLICATION",
136	        family: t.family,
137	        version: "",
138	        logo: t.family,
139	        vmid: 9000,
140	        baseVmid: 9000,
141	        setupScript: t.setupScript,
142	        minRamMB: t.minRamMB,
143	        minDiskGB: t.minDiskGB,
144	        licenseRequired: false,
145	        featured: false,
146	        sortOrder: sort++,
147	        active: true,
148	      },
149	      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
150	    });
151	    templateIdByFamily.set(t.family, os.id);
152	    console.log(`  osTemplate ${t.family.padEnd(15)} → ${os.id}`);
153	  }
154	
155	  // 2. GamePlans wired to a base VPS Plan (by RAM) + the game's OsTemplate.
156	  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
157	  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
158	  const largest = plans[plans.length - 1];
159	
160	  let created = 0;
161	  let updated = 0;
162	  const sortByGame = new Map<string, number>();
163	  for (const spec of TIERS) {
164	    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
165	    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
166	    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
167	    sortByGame.set(spec.gameFamily, sortOrder + 1);
168	
169	    const data = {
170	      gameFamily: spec.gameFamily,
171	      name: spec.name,
172	      ramMB: spec.ramMB,
173	      cpuCores: spec.cpuCores,
174	      diskGB: spec.diskGB,
175	      slots: spec.slots,
176	      priceCents: spec.priceCents,
177	      termMonths: 1,
178	      basePlanId: basePlan.id,
179	      osTemplateId: osId,
180	      featured: spec.featured ?? false,
181	      active: true,
182	      sortOrder,
183	    };
184	
185	    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
186	    if (existing) {
187	      await db.gamePlan.update({ where: { id: existing.id }, data });
188	      updated++;
189	    } else {
190	      await db.gamePlan.create({ data });
191	      created++;
192	    }
193	    console.log(`  plan ${spec.name.padEnd(38)} base=${basePlan.name} img=${osId ? "yes" : "auto"}`);
194	  }
195	
196	  console.log(`\nWave 1: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
197	}
198	
199	main()
200	  .catch((e) => {
201	    console.error(e);
202	    process.exit(1);
203	  })
204	  .finally(() => db.$disconnect());
