257	/** Next UTC occurrence of hour:minute strictly after `from` (schedule planning). */
258	export function computeNextRun(hour: number, minute: number, from: Date = new Date()): Date {
259	  const next = new Date(
260	    Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate(), hour, minute, 0, 0)
261	  );
262	  if (next.getTime() <= from.getTime()) next.setUTCDate(next.getUTCDate() + 1);
263	  return next;
264	}
265	
266	/** Next run for an interval-based schedule: `from + intervalMinutes`. */
267	export function computeNextIntervalRun(intervalMinutes: number, from: Date = new Date()): Date {
268	  return new Date(from.getTime() + intervalMinutes * 60_000);
269	}
