292	/**
293	 * A TCP port from an UNTRUSTED source (the customer's own config file, or a form).
294	 * Returns a 1..65535 integer or null — the parsed number, never the caller's text,
295	 * so it is safe by construction rather than by escaping.
296	 */
297	export function parsePort(raw: unknown): number | null {
298	  const n = Number(String(raw ?? "").trim());
299	  if (!Number.isInteger(n) || n < 1 || n > 65535) return null;
300	  return n;
301	}
302	
303	/**
304	 * A single RCON/console command line typed by the customer. Their own server, so
305	 * the verb set is intentionally open — but it is sent as a Source RCON packet body
306	 * (never a shell), and we still forbid NUL/newline/control chars (which would forge
307	 * multiple packets or corrupt framing) and bound the length.
308	 */
309	export function validateRconCommand(raw: string): { ok: true; command: string } | { ok: false; error: string } {
310	  const c = String(raw ?? "");
311	  if (c.trim().length === 0) return { ok: false, error: "Enter a command." };
312	  if (c.length > 512) return { ok: false, error: "Command is too long (max 512 chars)." };
313	  // eslint-disable-next-line no-control-regex
314	  if (/[\x00-\x1f\x7f]/.test(c)) return { ok: false, error: "Command may not contain line breaks or control characters." };
315	  return { ok: true, command: c.trim() };
316	}
317	
318	/**
319	 * A player identifier (name / SteamID / UID) used to build a kick/ban command.
320	 * Restricted to a shell-and-protocol-inert token so it can be interpolated into an
321	 * RCON verb template with no framing or word-splitting surprises.
322	 */
323	export function validatePlayerId(raw: string): { ok: true; id: string } | { ok: false; error: string } {
324	  const id = String(raw ?? "").trim();
325	  if (!/^[A-Za-z0-9_.:-]{1,64}$/.test(id)) return { ok: false, error: "Unsupported player identifier." };
326	  return { ok: true, id };
327	}
