329	/** Absolute path allowlist for a located config/data path (no traversal). */
330	const SAFE_PATH_RE = /^\/[A-Za-z0-9._/ -]{1,255}$/;
331	export function isSafeRemotePath(p: string): boolean {
332	  return typeof p === "string" && SAFE_PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
333	}
334	
335	/** Defensive POSIX single-quote (values are also allowlisted before reaching here). */
336	export function shq(s: string): string {
337	  return `'${String(s).replace(/'/g, `'\\''`)}'`;
338	}
