340	// ---------------------------------------------------------------------------
341	// Remote locate + config read (read-only, over the shared SSH `exec`)
342	// ---------------------------------------------------------------------------
343	
344	/**
345	 * Locate the first existing file: explicit candidates via `test -f`, then a
346	 * bounded `find` over `roots`. Candidate paths are compile-time constants; the
347	 * returned hit is re-validated against the path allowlist before any caller uses
348	 * it. Returns null when nothing matches.
349	 */
350	export async function remoteLocateFile(
351	  conn: Client,
352	  candidates: string[],
353	  roots: string[],
354	  name: string
355	): Promise<string | null> {
356	  const testExpr = candidates.map((p) => `if [ -f ${shq(p)} ]; then echo ${shq(p)}; exit 0; fi;`).join(" ");
357	  const findExpr = roots.length
358	    ? `for r in ${roots.map((r) => shq(r)).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name ${shq(name)} 2>/dev/null | head -1; done | head -1`
359	    : "true";
360	  const { stdout } = await exec(conn, `${testExpr} ${findExpr}`, QUICK_TIMEOUT_MS);
361	  const hit = stdout
362	    .split(/\r?\n/)
363	    .map((s) => s.trim())
364	    .find((s) => s.length > 0);
365	  return hit && isSafeRemotePath(hit) ? hit : null;
366	}
367	
368	/** Locate the first existing directory from a candidate list. */
369	export async function remoteLocateDir(conn: Client, candidates: string[]): Promise<string | null> {
370	  const expr = candidates.map((p) => `if [ -d ${shq(p)} ]; then echo ${shq(p)}; exit 0; fi;`).join(" ");
371	  const { stdout } = await exec(conn, expr, QUICK_TIMEOUT_MS);
372	  const hit = stdout
373	    .split(/\r?\n/)
374	    .map((s) => s.trim())
375	    .find((s) => s.length > 0);
376	  return hit && isSafeRemotePath(hit) ? hit : null;
377	}
