379	/** Read a small remote text file (or null). Uses `cat`, capped by head. */
380	async function readRemoteText(conn: Client, path: string): Promise<string | null> {
381	  if (!isSafeRemotePath(path)) return null;
382	  const { stdout, code } = await exec(conn, `cat ${shq(path)} 2>/dev/null | head -c 65536`, QUICK_TIMEOUT_MS);
383	  if (code !== 0 && stdout.length === 0) return null;
384	  return stdout;
385	}
