387	/** Parse a `key=value` / `key value` config into a lowercase-keyed map. */
388	function parseFlatConfig(text: string): Record<string, string> {
389	  const out: Record<string, string> = {};
390	  for (const line of text.split(/\r?\n/)) {
391	    const t = line.trim();
392	    if (!t || t.startsWith("#") || t.startsWith("//") || t.startsWith("!") || t.startsWith(";")) continue;
393	    let key: string;
394	    let val: string;
395	    const eq = t.indexOf("=");
396	    if (eq >= 0) {
397	      key = t.slice(0, eq).trim();
398	      val = t.slice(eq + 1).trim();
399	    } else {
400	      const sp = t.search(/\s/);
401	      if (sp < 0) continue;
402	      key = t.slice(0, sp).trim();
403	      val = t.slice(sp + 1).trim();
404	    }
405	    // Strip surrounding quotes.
406	    val = val.replace(/^"(.*)"$/, "$1").replace(/^'(.*)'$/, "$1");
407	    if (key) out[key.toLowerCase()] = val;
408	  }
409	  return out;
410	}
411	
412	/** Pull `Key=Value` pairs out of Palworld's `OptionSettings=(...)` blob. */
413	function parsePalworldIni(text: string): Record<string, string> {
414	  const out: Record<string, string> = {};
415	  const idx = text.indexOf("OptionSettings=(");
416	  const open = idx >= 0 ? text.indexOf("(", idx) : -1;
417	  const close = open >= 0 ? text.indexOf(")", open) : -1;
418	  if (open < 0 || close < 0) return out;
419	  const inner = text.slice(open + 1, close);
420	  let cur = "";
421	  let inQuote = false;
422	  const pairs: string[] = [];
423	  for (const ch of inner) {
424	    if (ch === '"') inQuote = !inQuote;
425	    if (ch === "," && !inQuote) {
426	      pairs.push(cur);
427	      cur = "";
428	    } else cur += ch;
429	  }
430	  if (cur) pairs.push(cur);
431	  for (const p of pairs) {
432	    const eq = p.indexOf("=");
433	    if (eq < 0) continue;
434	    let v = p.slice(eq + 1).trim();
435	    v = v.replace(/^"(.*)"$/, "$1");
436	    out[p.slice(0, eq).trim().toLowerCase()] = v;
437	  }
438	  return out;
439	}
440	
441	export type RconCreds =
442	  | { ok: true; port: number; password: string }
443	  | { ok: false; reason: string };
444	
445	/**
446	 * Read a game server's RCON credentials out of its own config file, over SSH.
447	 * The password is used ONLY as a Source RCON packet body downstream — never a
448	 * shell argument — and the port is parsed to an integer (`parsePort`), so neither
449	 * value can inject anywhere.
450	 */
451	export async function readRconCreds(conn: Client, spec: GameControlSpec): Promise<RconCreds> {
452	  const cfg = spec.rconConfig;
453	  if (spec.rcon !== "source" || !cfg) {
454	    return { ok: false, reason: `Remote console is not available for ${spec.label}.` };
455	  }
456	  const path = await remoteLocateFile(conn, cfg.candidates, cfg.findRoots, cfg.findName);
457	  if (!path) return { ok: false, reason: `Could not find ${spec.label}'s config file to read RCON settings.` };
458	  const text = await readRemoteText(conn, path);
459	  if (text == null) return { ok: false, reason: `Could not read ${spec.label}'s config file.` };
460	
461	  const map = cfg.kind === "palworld-ini" ? parsePalworldIni(text) : parseFlatConfig(text);
462	
463	  if (cfg.enableKey) {
464	    const en = (map[cfg.enableKey.toLowerCase()] ?? "").toLowerCase();
465	    if (en !== "true" && en !== "1" && en !== "on") {
466	      return { ok: false, reason: `RCON is not enabled in ${spec.label}'s config — enable it and restart to use the console.` };
467	    }
468	  }
469	  const password = map[cfg.passwordKey.toLowerCase()] ?? "";
470	  if (!password) return { ok: false, reason: `No RCON password is set in ${spec.label}'s config.` };
471	  if (password.length > 256) return { ok: false, reason: "RCON password in the config looks malformed." };
472	
473	  const port = cfg.portKey ? parsePort(map[cfg.portKey.toLowerCase()]) ?? cfg.defaultPort : cfg.defaultPort;
474	  return { ok: true, port, password };
475	}
