477	// ---------------------------------------------------------------------------
478	// Source RCON over an SSH-forwarded TCP channel
479	// ---------------------------------------------------------------------------
480	
481	const RCON_TYPE_AUTH = 3;
482	const RCON_TYPE_EXEC = 2;
483	const RCON_TYPE_RESPONSE = 0;
484	const RCON_ID_AUTH = 0x1;
485	const RCON_ID_CMD = 0x2;
486	const RCON_ID_END = 0x2711; // sentinel id for the trailing empty packet
487	
488	function rconPacket(id: number, type: number, body: string): Buffer {
489	  const bodyBuf = Buffer.from(body, "ascii");
490	  const buf = Buffer.alloc(bodyBuf.length + 14);
491	  buf.writeInt32LE(bodyBuf.length + 10, 0); // size = id(4)+type(4)+body+2 nulls
492	  buf.writeInt32LE(id, 4);
493	  buf.writeInt32LE(type, 8);
494	  bodyBuf.copy(buf, 12);
495	  // two trailing NUL bytes already zero from Buffer.alloc
496	  return buf;
497	}
