499	/**
500	 * Open a TCP channel to `host:port` on the game VM THROUGH the authenticated SSH
501	 * connection. The RCON port therefore never needs to be reachable off the box.
502	 */
503	export function forwardTcp(conn: Client, host: string, port: number, timeoutMs = 8000): Promise<Duplex> {
504	  return new Promise((resolve, reject) => {
505	    const timer = setTimeout(() => reject(new Error("Timed out opening RCON channel")), timeoutMs);
506	    conn.forwardOut("127.0.0.1", 0, host, port, (err, stream) => {
507	      clearTimeout(timer);
508	      if (err) return reject(err);
509	      resolve(stream as unknown as Duplex);
510	    });
511	  });
512	}
