514	export type RconResult = { ok: true; response: string } | { ok: false; error: string };
515	
516	/**
517	 * Speak Source RCON over `stream`: authenticate, run `command`, and read the
518	 * (possibly multi-packet) response, using a trailing empty packet as the
519	 * end-of-response sentinel. Never throws — resolves an {ok,error} result. The
520	 * password is only ever a packet body; the command was validated by the caller.
521	 */
522	export function sourceRcon(stream: Duplex, password: string, command: string, timeoutMs = 8000): Promise<RconResult> {
523	  return new Promise((resolve) => {
524	    let acc = Buffer.alloc(0);
525	    let authed = false;
526	    let response = "";
527	    let done = false;
528	
529	    const finish = (r: RconResult) => {
530	      if (done) return;
531	      done = true;
532	      clearTimeout(timer);
533	      try {
534	        stream.end();
535	      } catch {
536	        /* best effort */
537	      }
538	      resolve(r);
539	    };
540	    const timer = setTimeout(
541	      () => finish(authed ? { ok: true, response } : { ok: false, error: "RCON timed out (no response)." }),
542	      timeoutMs
543	    );
544	
545	    stream.on("data", (chunk: Buffer) => {
546	      acc = Buffer.concat([acc, chunk]);
547	      while (acc.length >= 4) {
548	        const size = acc.readInt32LE(0);
549	        if (size < 10 || size > 4110) return finish({ ok: false, error: "Malformed RCON response." });
550	        if (acc.length < size + 4) break;
551	        const id = acc.readInt32LE(4);
552	        const type = acc.readInt32LE(8);
553	        const body = acc.slice(12, 4 + size - 2).toString("ascii");
554	        acc = acc.slice(4 + size);
555	
556	        if (!authed) {
557	          // The auth response is a type-2 (AUTH_RESPONSE) packet; id === -1 on failure.
558	          if (type === RCON_TYPE_EXEC) {
559	            if (id === -1) return finish({ ok: false, error: "RCON authentication failed (wrong password)." });
560	            authed = true;
561	            stream.write(rconPacket(RCON_ID_CMD, RCON_TYPE_EXEC, command));
562	            stream.write(rconPacket(RCON_ID_END, RCON_TYPE_EXEC, "")); // sentinel
563	          }
564	          // A leading empty RESPONSE_VALUE some servers send pre-auth is ignored.
565	        } else {
566	          if (id === RCON_ID_END) return finish({ ok: true, response });
567	          if (type === RCON_TYPE_RESPONSE) response += body;
568	        }
569	      }
570	    });
571	    stream.on("error", (e: Error) => finish({ ok: false, error: e?.message || "RCON connection error." }));
572	    stream.on("close", () => finish(authed ? { ok: true, response } : { ok: false, error: "RCON connection closed." }));
573	
574	    stream.write(rconPacket(RCON_ID_AUTH, RCON_TYPE_AUTH, password));
575	  });
576	}
