578	/**
579	 * Full inline RCON round-trip on an already-open SSH connection: read creds from
580	 * the server's config, tunnel to 127.0.0.1:<port>, run one command. Callers guard
581	 * SANDBOX and ownership before reaching here.
582	 */
583	export async function runRcon(conn: Client, spec: GameControlSpec, command: string): Promise<RconResult> {
584	  const creds = await readRconCreds(conn, spec);
585	  if (!creds.ok) return { ok: false, error: creds.reason };
586	  let stream: Duplex;
587	  try {
588	    stream = await forwardTcp(conn, "127.0.0.1", creds.port);
589	  } catch (e) {
590	    return { ok: false, error: e instanceof Error ? e.message : "Could not open RCON channel." };
591	  }
592	  return sourceRcon(stream, creds.password, command);
593	}
