595	// ---------------------------------------------------------------------------
596	// Log / world / backup readers (read-only shell over the shared `exec`)
597	// ---------------------------------------------------------------------------
598	
599	/** Directory the platform writes game world backups to (fixed, never user input). */
600	export const GAME_BACKUP_DIR = "/var/backups/nxeon-game";
601	
602	export type LogResult = { ok: true; lines: string[]; unit: string | null } | { ok: false; error: string };
603	
604	/**
605	 * Tail the game service's recent logs. Resolves the unit from the family hints
606	 * (compile-time constants), then reads the last `n` journal lines; if journald has
607	 * nothing, falls back to a `.log` file under the data roots. Read-only.
608	 */
609	export async function readGameLogs(conn: Client, spec: GameControlSpec, n = 200): Promise<LogResult> {
610	  const lines = Math.min(Math.max(Math.trunc(n) || 200, 20), 500);
611	  const hints = spec.serviceHints.map(shq).join(" ");
612	  const roots = spec.dataRoots.map(shq).join(" ");
613	  const script = [
614	    `unit=""`,
615	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
616	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
617	    `echo "NXLOG:UNIT:${"$"}{unit:-none}"`,
618	    `if [ -n "$unit" ]; then journalctl -u "$unit" -n ${lines} --no-pager 2>/dev/null; fi`,
619	    // Fallback: newest *.log under the data roots (bounded).
620	    `f=""; for r in ${roots}; do [ -d "$r" ] && f=$(find "$r" -maxdepth 4 -type f -name '*.log' 2>/dev/null | head -1) && [ -n "$f" ] && break; done`,
621	    `if [ -n "$f" ]; then echo "NXLOG:FILE:$f"; tail -n ${lines} "$f" 2>/dev/null; fi`,
622	  ].join("\n");
623	  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
624	  const all = stdout.split(/\r?\n/);
625	  let unit: string | null = null;
626	  const out: string[] = [];
627	  for (const l of all) {
628	    const m = /^NXLOG:UNIT:(.*)$/.exec(l);
629	    if (m) {
630	      unit = m[1] === "none" ? null : m[1];
631	      continue;
632	    }
633	    if (/^NXLOG:FILE:/.test(l)) continue;
634	    out.push(l);
635	  }
636	  while (out.length && out[out.length - 1].trim() === "") out.pop();
637	  return { ok: true, lines: out.slice(-lines), unit };
638	}
