640	export type WorldEntry = { name: string; sizeBytes: number; isDir: boolean };
641	export type WorldResult = { ok: true; dir: string | null; entries: WorldEntry[] } | { ok: false; error: string };
642	
643	/** List the top-level world/save entries with sizes. Read-only. */
644	export async function readWorlds(conn: Client, spec: GameControlSpec): Promise<WorldResult> {
645	  const dir = await remoteLocateDir(conn, spec.dataRoots);
646	  if (!dir) return { ok: true, dir: null, entries: [] };
647	  // `du -sb` on each top-level entry: size<TAB>path. Bounded to 200 entries.
648	  const script =
649	    `cd ${shq(dir)} 2>/dev/null || exit 0; ` +
650	    `for e in * .*; do [ "$e" = "." ] || [ "$e" = ".." ] && continue; [ -e "$e" ] || continue; ` +
651	    `t=f; [ -d "$e" ] && t=d; sz=$(du -sb "$e" 2>/dev/null | cut -f1); printf '%s\\t%s\\t%s\\n' "$t" "${"$"}{sz:-0}" "$e"; done | head -200`;
652	  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
653	  const entries: WorldEntry[] = [];
654	  for (const line of stdout.split(/\r?\n/)) {
655	    const parts = line.split("\t");
656	    if (parts.length < 3) continue;
657	    const [t, sz, ...rest] = parts;
658	    const name = rest.join("\t").trim();
659	    if (!name) continue;
660	    entries.push({ name, sizeBytes: Number(sz) || 0, isDir: t === "d" });
661	  }
662	  return { ok: true, dir, entries };
663	}
664	
665	export type BackupEntry = { name: string; path: string; sizeBytes: number; modifiedMs: number };
666	export type BackupListResult = { ok: true; backups: BackupEntry[] } | { ok: false; error: string };
667	
668	/** List existing world backup archives the platform has created. Read-only. */
669	export async function readGameBackups(conn: Client): Promise<BackupListResult> {
670	  const script =
671	    `d=${shq(GAME_BACKUP_DIR)}; [ -d "$d" ] || exit 0; ` +
672	    `for f in "$d"/*.tar.gz; do [ -f "$f" ] || continue; ` +
673	    `sz=$(stat -c '%s' "$f" 2>/dev/null); mt=$(stat -c '%Y' "$f" 2>/dev/null); ` +
674	    `printf '%s\\t%s\\t%s\\n' "${"$"}{sz:-0}" "${"$"}{mt:-0}" "$f"; done | head -100`;
675	  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
676	  const backups: BackupEntry[] = [];
677	  for (const line of stdout.split(/\r?\n/)) {
678	    const parts = line.split("\t");
679	    if (parts.length < 3) continue;
680	    const path = parts.slice(2).join("\t").trim();
681	    if (!path || !isSafeRemotePath(path)) continue;
682	    backups.push({
683	      name: path.split("/").pop() || path,
684	      path,
685	      sizeBytes: Number(parts[0]) || 0,
686	      modifiedMs: (Number(parts[1]) || 0) * 1000,
687	    });
688	  }
689	  backups.sort((a, b) => b.modifiedMs - a.modifiedMs);
690	  return { ok: true, backups };
691	}
