693	// ---------------------------------------------------------------------------
694	// Player-list parsing (from RCON responses)
695	// ---------------------------------------------------------------------------
696	
697	export type Player = { name: string; extra?: string };
698	
699	/**
700	 * Parse the connected-player list out of a family's list-command RCON response.
701	 * Best-effort per family; unknown shapes return the raw response so the UI can
702	 * still show it.
703	 */
704	export function parsePlayers(family: GameFamily, response: string): { players: Player[]; raw: string } {
705	  const raw = response.trim();
706	  if (family === "minecraft") {
707	    // Strip ANSI escape codes — Paper/Spigot embed color codes in RCON responses.
708	    const clean = raw.replace(/\x1b\[[0-9;]*m/g, "");
709	    // Vanilla: "There are 2 of a max of 20 players online: Alice, Bob"
710	    const m1 = /players online:\s*(.+)$/im.exec(clean);
711	    if (m1) {
712	      const names = m1[1].split(",").map((s) => s.trim()).filter(Boolean);
713	      return { players: names.map((name) => ({ name })), raw };
714	    }
715	    // Paper: "There are 2 out of maximum 20 players online.\ndefault: Alice, Bob"
716	    const m2 = /players online\.\s*\n.*?:\s*(.+)$/im.exec(clean);
717	    if (m2) {
718	      const names = m2[1].split(",").map((s) => s.trim()).filter(Boolean);
719	      return { players: names.map((name) => ({ name })), raw };
720	    }
721	    return { players: [], raw };
722	  }
723	  if (family === "palworld") {
724	    // "name,playeruid,steamid" lines, first line is a header.
725	    const lines = raw.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
726	    const players: Player[] = [];
727	    for (const l of lines) {
728	      if (/^name\s*,/i.test(l)) continue;
729	      const cols = l.split(",");
730	      if (cols[0]) players.push({ name: cols[0].trim(), extra: cols.slice(1).join(",").trim() || undefined });
731	    }
732	    return { players, raw };
733	  }
734	  // cs2 `status` and anything else: hand back the raw block.
735	  return { players: [], raw };
736	}
